package co.kr.badara.dolswevoice;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;import java.util.concurrent.*;
final class AppUpdates {
 private final Activity activity;private final ExecutorService io=Executors.newSingleThreadExecutor();private volatile boolean closed,cancelled,busy;private boolean resumed,waitingPermission;private UpdateSpec pending;private ProgressDialog progress;
 AppUpdates(Activity a){activity=a;}
 void resume(){resumed=true;if(pending!=null){if(waitingPermission){waitingPermission=false;if(activity.getPackageManager().canRequestPackageInstalls())install();else notice("업데이트 파일은 준비됐어요. 설정에서 이 앱의 ‘알 수 없는 앱 설치’를 허용한 뒤 다시 업데이트를 확인해주세요.");}else install();}}
 void pause(){resumed=false;}
 private void ui(Runnable r){activity.runOnUiThread(()->{if(!closed&&!activity.isFinishing())r.run();});}
 void check(boolean manual){if(closed)return;if(busy){if(manual)notice("업데이트 확인 또는 다운로드 중입니다.");return;}busy=true;cancelled=false;io.execute(()->{try{JSONObject release=new JSONObject(read("https://api.github.com/repos/kojungho/dolswe-voice/releases/latest",2097152));JSONArray assets=release.optJSONArray("assets");String meta=null;if(assets!=null)for(int i=0;i<assets.length();i++){JSONObject a=assets.getJSONObject(i);if("update.json".equals(a.optString("name")))meta=a.optString("browser_download_url");}if(meta==null){if(manual)ui(()->notice("현재 공개된 버전에는 자동 업데이트 정보가 없습니다."));return;}String tag=release.getString("tag_name");if(!tag.matches("v[0-9]+\\.[0-9]+\\.[0-9]+")||!meta.equals(UpdateSpec.REPOSITORY+"/releases/download/"+tag+"/update.json"))throw new IOException("업데이트 정보 주소가 올바르지 않아요.");UpdateSpec spec=new UpdateSpec(read(meta,32768));if(!tag.equals("v"+spec.version))throw new IOException("업데이트 버전 정보가 일치하지 않아요.");long installed=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0).getLongVersionCode();if(spec.code<=installed){if(manual)ui(()->notice("최신 버전입니다."));return;}
  ui(()->{progress=new ProgressDialog(activity);progress.setTitle("새 버전 "+spec.version+" 다운로드");progress.setMessage("다운로드 후 안드로이드 설치 화면이 열립니다.");progress.setProgressStyle(ProgressDialog.STYLE_HORIZONTAL);progress.setMax(100);progress.setCancelable(true);progress.setOnCancelListener(d->cancelled=true);progress.show();});File file=UpdateApkProvider.file(activity);file.getParentFile().mkdirs();if(!file.exists()||file.length()!=spec.size||!sha(file).equals(spec.sha)){File partial=new File(file.getParentFile(),"download.part");try{HttpURLConnection conn=open(spec.url);try(InputStream in=conn.getInputStream();OutputStream out=new FileOutputStream(partial)){byte[] buffer=new byte[65536];int n;long total=0;int last=-1;MessageDigest hash=MessageDigest.getInstance("SHA-256");while((n=in.read(buffer))!=-1){if(cancelled||closed)throw new InterruptedIOException("다운로드를 취소했어요.");total+=n;if(total>spec.size)throw new IOException("파일 크기가 업데이트 정보와 달라요.");out.write(buffer,0,n);hash.update(buffer,0,n);int pct=(int)(total*100/spec.size);if(pct!=last){last=pct;ui(()->{if(progress!=null)progress.setProgress(pct);});}}if(total!=spec.size||!hex(hash.digest()).equals(spec.sha))throw new IOException("다운로드 파일 검사에 실패했어요. 다시 시도해주세요.");}finally{conn.disconnect();}verify(partial,spec);if(file.exists()&&!file.delete())throw new IOException("이전 업데이트 파일을 지우지 못했어요.");if(!partial.renameTo(file))throw new IOException("업데이트 파일을 저장하지 못했어요.");}finally{partial.delete();}}
  verify(file,spec);ui(()->{dismiss();pending=spec;if(resumed)install();});
 }catch(Exception error){if(manual||progress!=null)ui(()->{dismiss();notice(VoiceService.message(error));});}finally{busy=false;}});}
 private void verify(File file,UpdateSpec spec)throws Exception{PackageManager pm=activity.getPackageManager();PackageInfo apk=pm.getPackageArchiveInfo(file.toString(),PackageManager.GET_SIGNING_CERTIFICATES);PackageInfo own=pm.getPackageInfo(activity.getPackageName(),PackageManager.GET_SIGNING_CERTIFICATES);if(apk==null||!activity.getPackageName().equals(apk.packageName)||apk.getLongVersionCode()!=spec.code||!spec.version.equals(apk.versionName)||apk.getLongVersionCode()<=own.getLongVersionCode()||apk.signingInfo==null||own.signingInfo==null)throw new IOException("설치 파일의 앱 또는 버전 정보가 올바르지 않아요.");android.content.pm.Signature[] a=apk.signingInfo.getApkContentsSigners(),b=own.signingInfo.getApkContentsSigners();if(a.length!=1||b.length!=1||!Arrays.equals(a[0].toByteArray(),b[0].toByteArray()))throw new IOException("기존 앱과 서명이 달라 설치를 중단했어요.");}
 private void install(){if(pending==null||!resumed)return;if(!activity.getPackageManager().canRequestPackageInstalls()){waitingPermission=true;noticePermission();return;}try{File f=UpdateApkProvider.file(activity);if(!f.exists()||f.length()!=pending.size)throw new IOException("업데이트 파일이 없어요. 다시 확인해주세요.");Uri uri=Uri.parse("content://"+activity.getPackageName()+".updates/update.apk");Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("APK",uri));pending=null;activity.startActivity(intent);}catch(Exception e){notice("설치 화면을 열 수 없어요. "+VoiceService.message(e));}}
 private void noticePermission(){new AlertDialog.Builder(activity).setTitle("업데이트 설치 허용").setMessage("안드로이드 설정에서 돌쇠 음성비서의 ‘알 수 없는 앱 설치’를 허용해주세요. 돌아오면 설치 화면이 열립니다.").setPositiveButton("설정 열기",(d,w)->{try{activity.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())));}catch(Exception e){waitingPermission=false;notice("휴대폰 설정에서 이 앱의 설치 권한을 확인해주세요.");}}).setNegativeButton("나중에",(d,w)->{waitingPermission=false;pending=null;}).setOnCancelListener(d->{waitingPermission=false;pending=null;}).show();}
 static String sha(File f)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)digest.update(b,0,n);}return hex(digest.digest());}private static String hex(byte[] bytes){StringBuilder out=new StringBuilder();for(byte b:bytes)out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
 private static HttpURLConnection open(String address)throws Exception{for(int redirect=0;redirect<6;redirect++){URL u=new URL(address);String h=u.getHost();if(!"https".equals(u.getProtocol())||u.getUserInfo()!=null||!(h.equals("github.com")||h.equals("api.github.com")||h.endsWith(".githubusercontent.com")))throw new IOException("허용되지 않은 업데이트 주소예요.");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","DolsweVoice/1.1.0");int status=c.getResponseCode();if(status>=300&&status<400){String next=c.getHeaderField("Location");c.disconnect();if(next==null)throw new IOException("다운로드 주소를 찾지 못했어요.");address=new URL(u,next).toString();continue;}if(status!=200){c.disconnect();throw new IOException("업데이트 서버 연결 실패 ("+status+")");}return c;}throw new IOException("업데이트 연결 경로가 너무 많아요.");}
 private static String read(String url,int max)throws Exception{HttpURLConnection c=open(url);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("업데이트 정보가 너무 커요.");out.write(b,0,n);}return out.toString("UTF-8");}finally{c.disconnect();}}
 private void dismiss(){if(progress!=null){progress.dismiss();progress=null;}}private void notice(String s){if(!closed&&!activity.isFinishing())new AlertDialog.Builder(activity).setMessage(s).setPositiveButton("확인",null).show();}
 void close(){closed=true;cancelled=true;io.shutdownNow();dismiss();}
}
